"""matplotlib.backends.backend_gtk4agg — gtk4agg backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_gtk4agg import
FigureCanvasGTK4Agg`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasGTK4Agg = _make_canvas('FigureCanvasGTK4Agg', 'png')
FigureManagerGTK4Agg = _make_manager('FigureManagerGTK4Agg')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasGTK4Agg
FigureManager = FigureManagerGTK4Agg

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendGTK4Agg', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show
